-- Generated by: maple-proxy usage lake --catalog-dsn-env MAPLE_POSTGRES_DSN --data-env MAPLE_LAKE_DATA_PATH --emit-sql maintain
-- Maple: the lake's daily upkeep: write rows kept in the catalog out as Parquet, merge small files,
-- expire old snapshots and delete files nothing needs. Run it once a day.
INSTALL ducklake;
INSTALL postgres;
LOAD ducklake;
LOAD postgres;
CREATE OR REPLACE TEMPORARY SECRET maple_lake (TYPE ducklake, METADATA_PATH getenv('MAPLE_POSTGRES_DSN'), METADATA_SCHEMA 'maple_lake', DATA_PATH getenv('MAPLE_LAKE_DATA_PATH'), METADATA_PARAMETERS MAP {'TYPE': 'postgres'});
ATTACH 'ducklake:maple_lake' AS tgt (DATA_INLINING_ROW_LIMIT 10000);
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS tgt.main.usage ("at" TIMESTAMPTZ, "duration_ms" BIGINT, "requested" VARCHAR, "model" VARCHAR, "provider" VARCHAR, "streamed" BOOLEAN, "tools" BIGINT, "messages" BIGINT, "input_tokens" BIGINT, "output_tokens" BIGINT, "cached_tokens" BIGINT, "cache_write_tokens" BIGINT, "ai_units" DOUBLE, "error" VARCHAR, "client" VARCHAR, "agent" VARCHAR, "surface" VARCHAR, "prefix" VARCHAR, "setup" VARCHAR, "conv" VARCHAR, "fallback" BOOLEAN, "cache_class" VARCHAR, "cache_reason" VARCHAR, "schema_version" BIGINT, "session" VARCHAR, "warming" BOOLEAN, "cost_estimated" DOUBLE, "cost_currency" VARCHAR, "priced" BOOLEAN, "cache_saved_estimated" DOUBLE, "cache_write_surcharge_estimated" DOUBLE, "trim_saved_tokens_estimated" BIGINT, "trim_saved_estimated" DOUBLE, "trim_cost_estimated" DOUBLE, "images_saved_tokens_estimated" BIGINT, "images_saved_estimated" DOUBLE, "images_cost_estimated" DOUBLE, "snapshots_saved_tokens_estimated" BIGINT, "snapshots_saved_estimated" DOUBLE, "snapshots_cost_estimated" DOUBLE, "stabiliser_saved_estimated" DOUBLE, "warming_expected_saved_estimated" DOUBLE, "request_hash" VARCHAR, "cached_response" BOOLEAN, "response_cache_saved_estimated" DOUBLE, "person" VARCHAR, "team" VARCHAR, "agent_version" VARCHAR, "ttft_ms" BIGINT, "upstream_ms" BIGINT, "error_class" VARCHAR, "attempts" BIGINT, "first_choice" VARCHAR, "route_reason" VARCHAR, "auto_weight" VARCHAR, "auto_basis" VARCHAR, "cache_detail" VARCHAR, "tools_hash" VARCHAR, "system_hash" VARCHAR, "budget_scope" VARCHAR, "proxy_id" VARCHAR, "proxy_name" VARCHAR, "proxy_instance" VARCHAR, "origin_proxy" VARCHAR, "hops" BIGINT, "via" VARCHAR, "account_source" VARCHAR, "record_id" VARCHAR, "request_id" VARCHAR, "reported_by" VARCHAR, "source" VARCHAR, "forwarded" BOOLEAN, "loaded_from" VARCHAR, "loaded_at" TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS tgt.main.events ("at" TIMESTAMPTZ, "kind" VARCHAR, "subject" VARCHAR, "level" VARCHAR, "code" VARCHAR, "value" VARCHAR, "detail" VARCHAR, "loaded_from" VARCHAR, "loaded_at" TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS tgt.main.maple_state ("unit" VARCHAR, "kind" VARCHAR, "file_id" VARCHAR, "position" BIGINT, "updated_at" TIMESTAMPTZ);
COMMIT;
CALL tgt.set_option('target_file_size', '32MB');
CALL ducklake_flush_inlined_data('tgt', table_name => 'usage');
CALL ducklake_flush_inlined_data('tgt', table_name => 'events');
CALL ducklake_merge_adjacent_files('tgt', 'usage', max_file_size => 8000000);
CALL ducklake_merge_adjacent_files('tgt', 'events', max_file_size => 8000000);
CALL ducklake_expire_snapshots('tgt', older_than => now() - INTERVAL '30 days');
CALL ducklake_cleanup_old_files('tgt', older_than => now() - INTERVAL '1 day');
USE tgt;
BEGIN TRANSACTION;

-- Named views (--views): ready-made questions over the same records, in a schema of their own named
-- maple, so a view of yours outside it is never replaced. Columns added in a later schema version are
-- NULL on older lines: person reads 'unattributed', TTFT and upstream time are NULL before version 4.
CREATE SCHEMA IF NOT EXISTS maple;

-- maple.usage: the same as the usage view above, so the views below keep working if you change that one.
CREATE OR REPLACE VIEW maple.usage AS
SELECT * EXCLUDE ("loaded_from", "loaded_at") FROM main.usage
WHERE "source" IS DISTINCT FROM 'child';

-- maple.requests: every request, with its UTC day, an outcome (warming, cached, error, fallback or ok),
-- and person 'unattributed' where the line names none (every line before schema version 4).
CREATE OR REPLACE VIEW maple.requests AS
SELECT
  * REPLACE (COALESCE("person", 'unattributed') AS "person"),
  CAST(timezone('UTC', "at") AS DATE) AS "day",
  CASE
    WHEN COALESCE("warming", false) THEN 'warming'
    WHEN COALESCE("cached_response", false) THEN 'cached'
    WHEN "error" IS NOT NULL THEN 'error'
    WHEN "fallback" THEN 'fallback'
    ELSE 'ok'
  END AS "outcome"
FROM maple.usage;

-- maple.daily_spend: per UTC day, provider, model, person and team: requests, tokens, AI units and the
-- list-price estimate (an estimate, not a bill; never add it to ai_units), the proxies that recorded them
-- and why their accounts were used (schema version 5 on; NULL before).
CREATE OR REPLACE VIEW maple.daily_spend AS
SELECT
  "day", "provider", "model", "person", "team",
  count(*) AS "requests",
  sum("input_tokens") AS "input_tokens",
  sum("output_tokens") AS "output_tokens",
  sum("cached_tokens") AS "cached_tokens",
  sum("cache_write_tokens") AS "cache_write_tokens",
  sum("ai_units") AS "ai_units",
  sum("cost_estimated") AS "cost_estimated",
  string_agg(DISTINCT "cost_currency", ',') AS "cost_currency",
  string_agg(DISTINCT COALESCE("proxy_name", "proxy_id"), ',' ORDER BY COALESCE("proxy_name", "proxy_id")) AS "proxies",
  string_agg(DISTINCT "account_source", ',' ORDER BY "account_source") AS "account_sources"
FROM maple.requests
GROUP BY "day", "provider", "model", "person", "team";

-- maple.sessions: per session id (lines with one; schema version 2 on): first and last request, requests,
-- the models that answered, spend, and the share of requests the prompt cache classified as a hit, out
-- of those it classified at all (NULL when it classified none).
CREATE OR REPLACE VIEW maple.sessions AS
SELECT
  "session",
  min("at") AS "first_at",
  max("at") AS "last_at",
  count(*) AS "requests",
  string_agg(DISTINCT "model", ',' ORDER BY "model") AS "models",
  string_agg(DISTINCT "person", ',' ORDER BY "person") AS "people",
  sum("ai_units") AS "ai_units",
  sum("cost_estimated") AS "cost_estimated",
  count(*) FILTER (WHERE "cache_class" = 'hit') / NULLIF(count(*) FILTER (WHERE "cache_class" IN ('hit', 'partial', 'miss', 'lost')), 0) AS "cache_hit_rate"
FROM maple.requests
WHERE "session" IS NOT NULL
GROUP BY "session";

-- maple.people: per person and team: requests, spend and when they were active. Lines before schema
-- version 4 (and requests nobody was named for) count under 'unattributed'.
CREATE OR REPLACE VIEW maple.people AS
SELECT
  "person", "team",
  count(*) AS "requests",
  sum("ai_units") AS "ai_units",
  sum("cost_estimated") AS "cost_estimated",
  string_agg(DISTINCT "cost_currency", ',') AS "cost_currency",
  count(DISTINCT "day") AS "days_active",
  min("at") AS "first_at",
  max("at") AS "last_at",
  string_agg(DISTINCT "origin_proxy", ',' ORDER BY "origin_proxy") AS "origin_proxies",
  string_agg(DISTINCT "account_source", ',' ORDER BY "account_source") AS "account_sources"
FROM maple.requests
GROUP BY "person", "team";

-- maple.provider_health: per provider, model and UTC hour, for the requests that reached a provider (not
-- those answered from the response cache): errors, the error rate, errors by class (schema version 4 on),
-- and duration, upstream time and time to first token as medians and 95th percentiles. Upstream time and
-- TTFT are NULL before schema version 4, and TTFT is measured for streamed requests only.
CREATE OR REPLACE VIEW maple.provider_health AS
SELECT
  "provider", "model",
  date_trunc('hour', timezone('UTC', "at")) AS "hour",
  count(*) AS "requests",
  count("error") AS "errors",
  count("error") / count(*) AS "error_rate",
  histogram("error_class") FILTER (WHERE "error_class" IS NOT NULL) AS "errors_by_class",
  quantile_cont("duration_ms", 0.5) AS "duration_p50_ms",
  quantile_cont("duration_ms", 0.95) AS "duration_p95_ms",
  quantile_cont("upstream_ms", 0.5) AS "upstream_p50_ms",
  quantile_cont("upstream_ms", 0.95) AS "upstream_p95_ms",
  quantile_cont("ttft_ms", 0.5) AS "ttft_p50_ms",
  quantile_cont("ttft_ms", 0.95) AS "ttft_p95_ms",
  count("ttft_ms") AS "ttft_measured"
FROM maple.usage
WHERE NOT COALESCE("cached_response", false)
GROUP BY ALL;

-- maple.events: the events log (events-YYYY-MM-DD.jsonl next to the usage log's daily files): settings
-- changed, and later health changes and alerts. Events are not requests, so they are not in the views above.
CREATE OR REPLACE VIEW maple.events AS
SELECT * EXCLUDE ("loaded_from", "loaded_at") FROM main.events;

-- maple.alerts: the alert events (alert.fired, alert.resolved): when, the alert's scope (subject), its
-- rule (code), the measured figure (value) and level. None are written before alerts are set up.
CREATE OR REPLACE VIEW maple.alerts AS
SELECT
  "at",
  CASE "kind" WHEN 'alert.fired' THEN 'fired' WHEN 'alert.resolved' THEN 'resolved' ELSE "kind" END AS "state",
  "subject" AS "scope",
  "code" AS "rule",
  "level",
  "value",
  "detail"
FROM maple.events
WHERE "kind" LIKE 'alert.%';

-- maple.child_usage: the usage lines proxies below this hub sent up (source child), kept apart from its own
-- usage log. With maple.usage they make maple.hops.
CREATE OR REPLACE VIEW maple.child_usage AS
SELECT * EXCLUDE ("loaded_from", "loaded_at") FROM main.usage
WHERE "source" = 'child';

-- maple.hops: every line, this proxy's own (source local) and those sent up from below (source child): one
-- line per try on every proxy a request passed through. Add these up for load per proxy; use
-- maple.client_requests to count requests and spend once.
CREATE OR REPLACE VIEW maple.hops AS
SELECT * FROM maple.usage
UNION ALL BY NAME
SELECT * FROM maple.child_usage;

-- maple.client_requests: one row per client request across chained proxies: its first try on the proxy it
-- first reached (who asked, what for), with what it cost wherever it was served: ai_units_spent and
-- cost_estimated_spent add up every line of the request (by request_id) that was not passed on to a hub, so
-- spend counts once. lines is how many lines the request has across the proxies whose usage is here.
CREATE OR REPLACE VIEW maple.client_requests AS
WITH spend AS (
  SELECT "request_id",
    sum("ai_units") FILTER (WHERE NOT COALESCE("forwarded", false)) AS "ai_units_spent",
    sum("cost_estimated") FILTER (WHERE NOT COALESCE("forwarded", false)) AS "cost_estimated_spent",
    count(*) AS "lines"
  FROM maple.hops
  WHERE "request_id" IS NOT NULL
  GROUP BY "request_id"
)
SELECT h.*,
  CASE WHEN h."request_id" IS NULL THEN CASE WHEN COALESCE(h."forwarded", false) THEN 0 ELSE h."ai_units" END ELSE s."ai_units_spent" END AS "ai_units_spent",
  CASE WHEN h."request_id" IS NULL THEN CASE WHEN COALESCE(h."forwarded", false) THEN NULL ELSE h."cost_estimated" END ELSE s."cost_estimated_spent" END AS "cost_estimated_spent",
  COALESCE(s."lines", 1) AS "lines"
FROM maple.hops h
LEFT JOIN spend s ON s."request_id" = h."request_id"
WHERE COALESCE(h."hops", 0) = 0 AND COALESCE(h."attempts", 1) <= 1 AND NOT COALESCE(h."warming", false);

-- maple.proxies: per proxy that recorded lines here (by name, else id; NULL for lines before schema version 5)
-- and how they arrived (source, and the child that sent them up): lines, the client requests that started
-- there, the lines of requests that came through other proxies first, the first proxies those came from,
-- its running copies, and spend counted where it was spent.
CREATE OR REPLACE VIEW maple.proxies AS
SELECT
  COALESCE("proxy_name", "proxy_id") AS "proxy",
  "proxy_id", "source", "reported_by",
  count(*) AS "lines",
  count(*) FILTER (WHERE COALESCE("hops", 0) = 0 AND COALESCE("attempts", 1) <= 1 AND NOT COALESCE("warming", false)) AS "client_requests",
  count(*) FILTER (WHERE COALESCE("hops", 0) > 0) AS "chained_lines",
  string_agg(DISTINCT "origin_proxy", ',' ORDER BY "origin_proxy") AS "origin_proxies",
  string_agg(DISTINCT "proxy_instance", ',' ORDER BY "proxy_instance") AS "instances",
  sum("ai_units") AS "ai_units",
  sum("ai_units") FILTER (WHERE NOT COALESCE("forwarded", false)) AS "ai_units_spent",
  sum("cost_estimated") FILTER (WHERE NOT COALESCE("forwarded", false)) AS "cost_estimated_spent",
  min("at") AS "first_at",
  max("at") AS "last_at"
FROM maple.hops
GROUP BY ALL;

-- maple.origins: per first proxy (origin_proxy), person and team: client requests, counted once, and what they
-- cost wherever they were served (from maple.client_requests).
CREATE OR REPLACE VIEW maple.origins AS
SELECT
  "origin_proxy", COALESCE("person", 'unattributed') AS "person", "team",
  count(*) AS "client_requests",
  sum("ai_units_spent") AS "ai_units_spent",
  sum("cost_estimated_spent") AS "cost_estimated_spent",
  sum("lines") AS "lines",
  min("at") AS "first_at",
  max("at") AS "last_at"
FROM maple.client_requests
GROUP BY ALL;
COMMIT;
USE memory;
